toolScript:
(() => {
  let animActive = true;
  let animId = null;
  let lastTime = performance.now();
  let deltas = [];
  let barX = 0;
  let barDirection = 1;
  const speedPxPerSec = 960;

  const fpsVal = document.getElementById('tv-fps-val');
  const fpsSub = document.getElementById('tv-fps-sub');
  const deltaVal = document.getElementById('tv-delta-val');
  const stabilityVal = document.getElementById('tv-stability-val');
  const hdrVal = document.getElementById('tv-hdr-val');
  const hdrSub = document.getElementById('tv-hdr-sub');
  const gamutVal = document.getElementById('tv-gamut-val');
  const depthVal = document.getElementById('tv-depth-val');
  const toggleBtn = document.getElementById('tv-toggle-anim');
  const fsBtn = document.getElementById('tv-fullscreen-btn');
  const canvasContainer = document.getElementById('tv-canvas-container');
  const canvas = document.getElementById('tv-motion-canvas');
  const ctx = canvas.getContext('2d');

  const resSelect = document.getElementById('tv-res-select');
  const hzSelect = document.getElementById('tv-hz-select');
  const colorDepthSelect = document.getElementById('tv-color-depth-select');
  const chromaSelect = document.getElementById('tv-chroma-select');
  const calcBwEl = document.getElementById('tv-calc-bw');
  const calcStdEl = document.getElementById('tv-calc-standard');
  const bwCard = document.getElementById('tv-bandwidth-result');

  function resizeCanvas() {
    const rect = canvasContainer.getBoundingClientRect();
    canvas.width = rect.width * (window.devicePixelRatio || 1);
    canvas.height = rect.height * (window.devicePixelRatio || 1);
  }
  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();

  function inspectDisplayQueries() {
    const isHdr = window.matchMedia && window.matchMedia('(dynamic-range: high)').matches;
    const isP3 = window.matchMedia && window.matchMedia('(color-gamut: p3)').matches;
    const isRec2020 = window.matchMedia && window.matchMedia('(color-gamut: rec2020)').matches;
    const depth = window.screen.colorDepth || 24;

    if (isHdr) {
      hdrVal.textContent = 'HDR Active';
      hdrVal.className = 'text-2xl font-black text-emerald-600';
      hdrSub.textContent = 'High dynamic range enabled';
    } else {
      hdrVal.textContent = 'SDR Standard';
      hdrVal.className = 'text-2xl font-black text-slate-700';
      hdrSub.textContent = 'Standard dynamic range detected';
    }

    if (isRec2020) {
      gamutVal.textContent = 'Rec. 2020';
      gamutVal.className = 'text-2xl font-black text-purple-600';
    } else if (isP3) {
      gamutVal.textContent = 'Display P3';
      gamutVal.className = 'text-2xl font-black text-indigo-600';
    } else {
      gamutVal.textContent = 'sRGB Standard';
      gamutVal.className = 'text-2xl font-black text-slate-700';
    }

    const bitsPerChannel = Math.round(depth / 3);
    depthVal.textContent = `Panel depth: ${depth}-bit (${bitsPerChannel}-bit/channel)`;
  }

  function updateBandwidth() {
    const resParts = resSelect.value.split('x');
    const w = parseInt(resParts[0], 10);
    const h = parseInt(resParts[1], 10);
    const hz = parseInt(hzSelect.value, 10);
    const bitDepth = parseInt(colorDepthSelect.value, 10);
    const chroma = chromaSelect.value;

    let bitsPerPixel = bitDepth * 3;
    if (chroma === '422') bitsPerPixel = bitDepth * 2;
    if (chroma === '420') bitsPerPixel = bitDepth * 1.5;

    const totalClockPixels = w * h * hz * 1.15;
    const rawBitsPerSec = totalClockPixels * bitsPerPixel;
    const gbps = (rawBitsPerSec / 1e9) * 1.2;
    calcBwEl.textContent = gbps.toFixed(1) + ' Gbps';

    if (gbps > 48.0) {
      bwCard.className = 'p-4 rounded-xl border border-rose-200 bg-rose-50 text-rose-950 space-y-1';
      calcStdEl.textContent = 'Exceeds standard HDMI 2.1 (48 Gbps) without Display Stream Compression (DSC).';
    } else if (gbps > 18.0) {
      bwCard.className = 'p-4 rounded-xl border border-indigo-200 bg-indigo-50 text-indigo-950 space-y-1';
      calcStdEl.textContent = 'Requires HDMI 2.1 Ultra High Speed connection (FRL 40/48 Gbps).';
    } else {
      bwCard.className = 'p-4 rounded-xl border border-emerald-200 bg-emerald-50 text-emerald-950 space-y-1';
      calcStdEl.textContent = 'Fits within standard HDMI 2.0 (18.0 Gbps TMDS) connection.';
    }
  }

  resSelect.addEventListener('change', updateBandwidth);
  hzSelect.addEventListener('change', updateBandwidth);
  colorDepthSelect.addEventListener('change', updateBandwidth);
  chromaSelect.addEventListener('change', updateBandwidth);

  function tick(now) {
    const dt = now - lastTime;
    lastTime = now;

    if (dt > 2 && dt < 60) {
      deltas.push(dt);
      if (deltas.length > 90) deltas.shift();
    }

    if (deltas.length > 20) {
      const mean = deltas.reduce((a, b) => a + b, 0) / deltas.length;
      const currentFps = Math.round(1000 / mean);
      fpsVal.textContent = String(currentFps);
      deltaVal.textContent = mean.toFixed(2);

      const variance = deltas.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / deltas.length;
      const stdDev = Math.sqrt(variance);
      const stability = Math.max(0, Math.min(100, Math.round(100 - stdDev * 15)));
      stabilityVal.textContent = `Stability: ${stability}% (StdDev ${stdDev.toFixed(1)}ms)`;

      if (currentFps >= 115) {
        fpsSub.textContent = 'High Refresh 120Hz+ Active';
        fpsSub.className = 'text-[11px] font-bold text-emerald-600 block mt-1';
      } else if (currentFps >= 57) {
        fpsSub.textContent = 'Standard 60Hz Pacing Normal';
        fpsSub.className = 'text-[11px] font-medium text-slate-600 block mt-1';
      } else {
        fpsSub.textContent = 'Frame Drops / Stutter Detected';
        fpsSub.className = 'text-[11px] font-bold text-rose-600 block mt-1';
      }
    }

    if (animActive) {
      const w = canvas.width;
      const h = canvas.height;
      const barWidth = w * 0.08;
      const travelDist = (speedPxPerSec * (dt / 1000)) * (window.devicePixelRatio || 1);

      barX += travelDist * barDirection;
      if (barX + barWidth >= w) {
        barX = w - barWidth;
        barDirection = -1;
      } else if (barX <= 0) {
        barX = 0;
        barDirection = 1;
      }

      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, w, h);

      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      const step = w / 16;
      for (let x = 0; x < w; x += step) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, h);
        ctx.stroke();
      }

      ctx.fillStyle = '#EE6C4D';
      ctx.fillRect(barX, 0, barWidth, h);
    }

    animId = requestAnimationFrame(tick);
  }

  toggleBtn.addEventListener('click', () => {
    animActive = !animActive;
    toggleBtn.textContent = animActive ? 'Pause Pattern' : 'Resume Pattern';
    if (animActive) {
      lastTime = performance.now();
    }
  });

  fsBtn.addEventListener('click', () => {
    if (!document.fullscreenElement) {
      canvasContainer.requestFullscreen().catch(() => {});
    } else {
      document.exitFullscreen().catch(() => {});
    }
  });

  document.addEventListener('fullscreenchange', () => {
    setTimeout(resizeCanvas, 100);
  });

  inspectDisplayQueries();
  updateBandwidth();
  animId = requestAnimationFrame(tick);
})();
